import { createHash, randomUUID } from "node:crypto";
import { constants, createWriteStream } from "node:fs";
import { Readable, Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import {
  lstat,
  mkdir,
  mkdtemp,
  open,
  readFile,
  writeFile,
  rm,
  rename,
} from "node:fs/promises";
import { join, sep } from "node:path";
import { homedir } from "node:os";
import { setTimeout as wait } from "node:timers/promises";
import { createBrowserDashboard } from "./browser-dashboard.mjs";

const execute = promisify(execFile);
const root = () =>
  join(homedir(), "Library/Application Support/Kaijan/Browser Viewer");

async function verifyCacheDirectory(path) {
  if (!(await lstat(path)).isDirectory())
    throw Error("Browser viewer cache path is not a directory");
}

function parseReceipt(contents, kind) {
  try {
    return JSON.parse(contents);
  } catch {
    // Parsing errors can quote the receipt in the saved Run status.
    throw Error(`Invalid browser viewer ${kind} receipt`);
  }
}

async function verifyApplication(application, selected, signal) {
  await execute(
    "/usr/bin/codesign",
    ["--verify", "--deep", "--strict", application],
    { signal },
  );
  const identity = await execute(
    "/usr/bin/codesign",
    ["-d", "--verbose=4", application],
    { signal },
  );
  if (
    !identity.stderr
      .split("\n")
      .includes(`TeamIdentifier=${selected.teamId}`) ||
    !identity.stderr.split("\n").includes("Identifier=ai.kaijan.browser-viewer")
  )
    throw Error("Browser viewer signing identity does not match its release");
  await execute(
    "/usr/sbin/spctl",
    ["--assess", "--type", "execute", application],
    { signal },
  );
}

async function findManualApplications(selected, signal) {
  if (process.platform !== "darwin") return [];
  // NSBundle uses Mach-O CPU types for its executable architectures.
  const architecture = process.arch === "arm64" ? 0x0100000c : 0x01000007;
  const { stdout } = await execute(
    "/usr/bin/osascript",
    [
      "-l",
      "JavaScript",
      "-e",
      `ObjC.import("AppKit");
      function run([version, architecture]) {
        const urls = $.NSWorkspace.sharedWorkspace.URLsForApplicationsWithBundleIdentifier("ai.kaijan.browser-viewer");
        const paths = [];
        for (let i = 0; i < urls.count; i++) {
          const url = urls.objectAtIndex(i);
          const bundle = $.NSBundle.bundleWithURL(url);
          if (bundle.isNil()) continue;
          const installed = ObjC.unwrap(bundle.objectForInfoDictionaryKey("CFBundleShortVersionString"));
          const architectures = ObjC.deepUnwrap(bundle.executableArchitectures) || [];
          if (installed === version && architectures.includes(Number(architecture)))
            paths.push(ObjC.unwrap(url.path));
        }
        return JSON.stringify(paths);
      }`,
      selected.version,
      String(architecture),
    ],
    { signal },
  );
  return JSON.parse(stdout);
}

async function browserCompanion(
  manifest,
  canDownload,
  {
    signal,
    storage = root(),
    findInstalledApplications = findManualApplications,
    // Platform trust boundary; ordinary hosts use the macOS verifier above.
    admitApplication = verifyApplication,
  } = {},
) {
  const selected = manifest?.[`${process.platform}-${process.arch}`];
  if (!selected)
    throw Error("Browser viewer is not available for this platform");
  const digest = selected.sha256;
  if (
    typeof digest !== "string" ||
    digest.length !== 64 ||
    /[^a-f0-9]/.test(digest)
  )
    throw Error("Browser viewer release has an invalid SHA-256 digest");
  const versions = join(storage, "versions");
  const generation = join(versions, digest);
  const receiptPath = join(generation, "installed.json");
  const installedApplication = join(generation, "Kaijan Browser.app");
  const verifyReceipt = async () => {
    await verifyCacheDirectory(versions);
    await verifyCacheDirectory(generation);
    const receiptFile = await open(
      receiptPath,
      constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK,
    );
    try {
      if (!(await receiptFile.stat()).isFile())
        throw Error("Browser viewer install receipt is not a regular file");
      const receipt = parseReceipt(
        await receiptFile.readFile("utf8"),
        "install",
      );
      if (receipt.sha256 !== digest)
        throw Error("Browser viewer release changed");
    } finally {
      await receiptFile.close();
    }
  };
  const existing = async () => {
    await verifyReceipt();
    await verifyCacheDirectory(installedApplication);
    return installedApplication;
  };
  try {
    return await existing();
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }
  const manualApplications = await findInstalledApplications(
    selected,
    signal,
  ).catch(() => []);
  signal?.throwIfAborted();
  for (const application of manualApplications) {
    if (application.startsWith(versions + sep)) continue;
    try {
      await admitApplication(application, selected, signal);
      signal?.throwIfAborted();
      return application;
    } catch {
      signal?.throwIfAborted();
    }
  }
  if (!canDownload) return;

  await mkdir(versions, { recursive: true, mode: 0o700 });
  await verifyCacheDirectory(versions);
  const temporary = await mkdtemp(join(versions, ".download-"));
  try {
    const response = await fetch(selected.url, { signal, redirect: "follow" });
    if (!response.ok) throw Error("Browser viewer download failed");
    const archive = join(temporary, "viewer.zip");
    const hash = createHash("sha256");
    const observe = new Transform({
      transform(chunk, _encoding, callback) {
        hash.update(chunk);
        callback(null, chunk);
      },
    });
    await pipeline(
      Readable.fromWeb(response.body),
      observe,
      createWriteStream(archive, { mode: 0o600, flags: "wx" }),
      { signal },
    );
    if (hash.digest("hex") !== digest)
      throw Error(
        "Browser viewer download does not match the selected release",
      );
    await execute("/usr/bin/ditto", ["-xk", archive, temporary], { signal });
    await rm(archive);
    const application = join(temporary, "Kaijan Browser.app");
    await admitApplication(application, selected, signal);
    await writeFile(
      join(temporary, "installed.json"),
      JSON.stringify({ sha256: digest, version: selected.version }),
      { mode: 0o600, flag: "wx" },
    );
    try {
      await rename(temporary, generation);
    } catch (error) {
      if (!["EEXIST", "ENOTEMPTY"].includes(error.code)) throw error;
      // A matching receipt can survive removal of the bundle. Publish only
      // the verified replacement, so a concurrent installer keeps its copy.
      await verifyReceipt();
      try {
        await verifyCacheDirectory(installedApplication);
      } catch (missing) {
        if (missing.code !== "ENOENT") throw missing;
        try {
          await rename(application, installedApplication);
        } catch (occupied) {
          if (!["EEXIST", "ENOTEMPTY"].includes(occupied.code)) throw occupied;
        }
      }
    }
    return await existing();
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}

async function readBrowserViewerRelease() {
  return JSON.parse(
    await readFile(new URL("./viewer-release.json", import.meta.url), "utf8"),
  );
}

/** Setup may acquire the exact release selected by the installed package. */
export async function prepareBrowserCompanion(manifest, options) {
  return browserCompanion(
    manifest ?? (await readBrowserViewerRelease()),
    true,
    options,
  );
}

/** Runner looks for a prepared companion without downloading an archive. */
export function findBrowserCompanion(manifest, options) {
  return browserCompanion(manifest, false, options);
}

/** The worker keeps browser ownership; companion registration is optional. */
export async function attachBrowserViewer(
  { context, control },
  { signal, runId, title, manifest, onUnavailable = () => {} } = {},
) {
  const dashboard = await createBrowserDashboard(context, control);
  const lifetime = new AbortController();
  const stop = () => lifetime.abort(signal.reason);
  if (signal?.aborted) stop();
  else signal?.addEventListener("abort", stop, { once: true });
  let requestFile;
  let status = { state: "preparing" };
  const preparation = (async () => {
    const release = manifest ?? (await readBrowserViewerRelease());
    const application = await findBrowserCompanion(release, {
      signal: lifetime.signal,
    });
    lifetime.signal.throwIfAborted();
    if (!application) throw Error("Browser viewer is not installed");
    await mkdir(join(root(), "requests"), { recursive: true, mode: 0o700 });
    requestFile = join(root(), "requests", randomUUID() + ".json");
    await writeFile(
      requestFile,
      JSON.stringify({ id: runId, title, url: dashboard.url }),
      { mode: 0o600, flag: "wx" },
    );
    // macOS's background launch preserves the person's foreground application.
    await execute(
      "/usr/bin/open",
      ["-g", "-n", application, "--args", `--run-file=${requestFile}`],
      { signal: lifetime.signal },
    );
    // Launch acknowledgment alone did not establish a responding app in the
    // first native flow. Wait for this registration's private receiving receipt.
    for (;;) {
      lifetime.signal.throwIfAborted();
      try {
        const receipt = parseReceipt(
          await readFile(requestFile + ".ack", "utf8"),
          "registration",
        );
        if (receipt.protocol === 1 && receipt.status === "registered") {
          status = { state: "ready", version: receipt.version };
          break;
        }
        if (receipt.protocol === 1 && receipt.status === "unavailable")
          throw Error("Browser view unavailable");
      } catch (error) {
        if (error.code !== "ENOENT") throw error;
      }
      await wait(100, undefined, { signal: lifetime.signal });
    }
  })().catch((error) => {
    if (!lifetime.signal.aborted) {
      status = { state: "unavailable", reason: String(error) };
      onUnavailable(error);
    }
  });
  return {
    ...dashboard,
    status: () => ({ ...status }),
    async close() {
      signal?.removeEventListener("abort", stop);
      lifetime.abort();
      await preparation;
      if (requestFile) {
        await rm(requestFile, { force: true });
        await rm(requestFile + ".ack", { force: true });
      }
      await dashboard.close();
    },
  };
}
